        code: 'from pydantic import BaseModel, Field\n\nclass ItemCreate(BaseModel):\n    code: str = Field(min_length=8, max_length=32, strict=True)\n    name: str\n\n@app.post("/items")\ndef create_item(item: ItemCreate):\n    return {"code": item.code, "name": item.name}',
