        code: 'from fastapi import BackgroundTasks\n\ndef send_notice(user_id: int):\n    ...\n\n@app.post("/orders")\ndef create_order(background_tasks: BackgroundTasks):\n    background_tasks.add_task(send_notice, 42)\n    return {"created": True}',
