        code: 'from fastapi.responses import StreamingResponse\n\nasync def stream_bytes():\n    yield b"first chunk\\n"\n    yield b"second chunk\\n"\n\n@app.get("/download")\nasync def download():\n    return StreamingResponse(\n        stream_bytes(),\n        media_type="application/octet-stream",\n    )',
