        code: 'import pytest\nfrom httpx import ASGITransport, AsyncClient\n\n@pytest.mark.anyio\nasync def test_items():\n    transport = ASGITransport(app=app)\n    async with AsyncClient(\n        transport=transport,\n        base_url="http://test",\n    ) as client:\n        response = await client.get("/items")\n    assert response.status_code == 200',
